def sym(g):
    n=len(g)
    return all(g[r][c]==g[n-1-r][n-1-c] for r in range(n) for c in range(n))
def symv(g): # left-right mirror
    n=len(g)
    return all(g[r][c]==g[r][n-1-c] for r in range(n) for c in range(n))
def symh(g):
    n=len(g)
    return all(g[r][c]==g[n-1-r][c] for r in range(n) for c in range(n))
